<script setup lang="ts">
import {localFetch,readJson} from './http'
import {computed,ref,onMounted,onUnmounted} from 'vue'
import Icon from './Icon.vue'
type Contributor={name:string;broker:string;branch:string;net:number;net_value:number|null}
type Stock={symbol:string;name:string}
type ConsensusRow=Stock&{close:number|null;buy_count:number;sell_count:number;buy_lots:number;sell_lots:number;net:number;buy_value:number|null;sell_value:number|null;net_value:number|null;buyers:Contributor[];sellers:Contributor[]}
type TurnoverRow=Stock&{rank:number;amount:number;close:number|null;market:string;appearances:number}
type RsRow=Stock&{rs20:number;rs_ytd:number;return20:number;ytd_pct:number;excess_pct:number}
type Report={consensus:{as_of:string|null;available_dates:string[];rows:ConsensusRow[];observed:number;total:number;missing:string[]};turnover:{as_of:string|null;available_dates:string[];rows:TurnoverRow[];sources:string[];start:string;fetched_at:string|null};rs:{as_of:string|null;rows:RsRow[];index_ytd?:number};tags:Record<string,string>;sector_memberships:Record<string,string[]>;sector_classification:{snapshot:string|null;error:string;groups:{name:string;parent:string}[]};job:null|{status:string;message:string}}
const emit=defineEmits<{rs:[];sector:[name:string]}>()
const report=ref<Report|null>(null),tab=ref('consensus'),rankMetric=ref<'lots'|'value'>('lots'),error=ref(''),date=ref(''),turnoverDate=ref(''),search=ref(''),minimum=ref<number|string>(2),expanded=ref(''),sector=ref(''),loading=ref(false),starting=ref(false)
let alive=true,epoch=0,timer:ReturnType<typeof setTimeout>|undefined
const running=computed(()=>starting.value||report.value?.job?.status==='running')
const fmt=(n:number|null|undefined,d=0)=>n==null?'—':n.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const signed=(n:number|undefined,d=0)=>n==null?'—':(n>0?'+':'')+fmt(n,d)
const money=(n:number|null|undefined)=>n==null?'—':(n>0?'+':'')+fmt(n/1e8,2)
const tone=(n:number|null|undefined)=>n==null?'muted':n>0?'positive':n<0?'negative':'muted'
const matches=(r:Stock)=>!search.value.trim()||(r.symbol+' '+r.name+' '+(report.value?.tags[r.symbol]||'')).toLowerCase().includes(search.value.trim().toLowerCase())
const minCount=computed(()=>Math.max(2,Math.floor(Number(minimum.value)||2)))
const rankings=computed(()=>['buy','sell'].map(side=>{
 const count=(r:ConsensusRow)=>side==='buy'?r.buy_count:r.sell_count
 const lots=(r:ConsensusRow)=>side==='buy'?r.buy_lots:r.sell_lots
 const value=(r:ConsensusRow)=>side==='buy'?r.buy_value:r.sell_value
 const rows=(report.value?.consensus.rows||[]).filter(r=>matches(r)&&count(r)>=minCount.value&&(rankMetric.value==='lots'||value(r)!=null))
 rows.sort((a,b)=>rankMetric.value==='value'?(value(b)!-value(a)!||count(b)-count(a)||lots(b)-lots(a)||a.symbol.localeCompare(b.symbol)):(count(b)-count(a)||lots(b)-lots(a)||a.symbol.localeCompare(b.symbol)))
 return {side,title:side==='buy'?'同步買超':'同步賣超',rows:rows.slice(0,30)}
}))
const memberships=(symbol:string)=>report.value?.sector_memberships?.[symbol]||[]
const totalAmount=computed(()=>(report.value?.turnover.rows||[]).reduce((sum,row)=>sum+row.amount,0))
const turnoverRows=computed(()=>(report.value?.turnover.rows||[]).filter(r=>matches(r)&&(!sector.value||(sector.value==='未分類'?!memberships(r.symbol).length:memberships(r.symbol).includes(sector.value)))))
const sectorStats=computed(()=>{
 const groups:Record<string,{name:string;amount:number;count:number}>={}
 for(const r of report.value?.turnover.rows||[]){for(const name of memberships(r.symbol).length?memberships(r.symbol):['未分類']){const g=groups[name]||(groups[name]={name,amount:0,count:0});g.amount+=r.amount;g.count++}}
 return Object.values(groups).sort((a,b)=>b.amount-a.amount)
})
const rsRows=computed(()=>(report.value?.rs.rows||[]).filter(matches))
function choose(value:string){tab.value=value;search.value='';expanded.value=''}
async function load(){
 const id=++epoch;loading.value=true;clearTimeout(timer)
 const q=new URLSearchParams();if(date.value)q.set('date',date.value);if(turnoverDate.value)q.set('turnover_date',turnoverDate.value)
 try{const response=await localFetch('/api/broker-focus?'+q);const data=await readJson(response);if(!alive||id!==epoch)return;if(!response.ok)throw new Error(data.error||'無法讀取券商關注');report.value=data;error.value='';if(data.job?.status==='running')timer=setTimeout(()=>{void load()},2500)}catch(e){if(alive&&id===epoch)error.value=(e as Error).message}finally{if(alive&&id===epoch)loading.value=false}
}
async function refresh(){starting.value=true;try{const r=await localFetch('/api/broker-focus/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const d=await readJson(r);if(!r.ok)throw new Error(d.error||'無法啟動回補');await load()}catch(e){error.value=(e as Error).message}finally{starting.value=false}}
onMounted(()=>{void load()});onUnmounted(()=>{alive=false;epoch++;clearTimeout(timer)})
</script>
<template>
 <div class="broker-focus">
  <header class="page-header"><div><div class="eyebrow">BROKER WATCHLIST</div><h1>券商關注</h1><p>一起買進的分點、資金停留的族群，以及長短期都強勢的個股。</p></div><button class="secondary" :disabled="loading" @click="load"><Icon name="refresh" :size="17"/>讀取最新本機統計</button></header>
  <div class="focus-tabs" role="tablist" aria-label="券商關注檢視"><button v-for="item in [{id:'consensus',name:'券商同步買賣超'},{id:'turnover',name:'每日成交重心'},{id:'rs',name:'RS 雙強名單'}]" :key="item.id" role="tab" :aria-selected="tab===item.id" :class="{selected:tab===item.id}" @click="choose(item.id)">{{item.name}}</button></div>
  <div v-if="error" class="error-banner" role="alert">{{error}}<button @click="load">重新讀取</button></div>
  <p v-if="!report" class="watch-loading">正在讀取本機統計…</p>
  <template v-if="report"><div v-if="report.sector_classification.error" class="error-banner">{{report.sector_classification.error}}</div>
   <div class="focus-toolbar"><label class="focus-search"><Icon name="search" :size="16"/><input v-model="search" placeholder="搜尋代碼、個股或族群" aria-label="搜尋券商關注個股"></label><template v-if="tab==='consensus'"><label>統計日期 <select v-model="date" aria-label="券商同步統計日期" @change="expanded='';load()"><option value="">最新 · {{report.consensus.available_dates[0]||'尚無資料'}}</option><option v-for="d in report.consensus.available_dates" :key="d">{{d}}</option></select></label><label>至少 <input v-model="minimum" type="number" min="2" :max="Math.max(2,report.consensus.total)" class="focus-number" aria-label="最少同步分點家數"> 家</label><div class="segmented" role="tablist" aria-label="券商同步排行口徑"><button role="tab" :aria-selected="rankMetric==='lots'" :class="{selected:rankMetric==='lots'}" @click="rankMetric='lots'">張數</button><button role="tab" :aria-selected="rankMetric==='value'" :class="{selected:rankMetric==='value'}" @click="rankMetric='value'">金額</button></div></template><template v-else-if="tab==='turnover'"><label>交易日期 <select v-model="turnoverDate" aria-label="成交重心日期" @change="sector='';load()"><option value="">最新 · {{report.turnover.available_dates[0]||'尚無資料'}}</option><option v-for="d in report.turnover.available_dates" :key="d">{{d}}</option></select></label><button class="primary" :disabled="running" @click="refresh"><Icon name="refresh" :size="16" :class="{spinning:running}"/>{{running?'成交重心回補中':'更新並補齊成交重心'}}</button></template><button v-else class="secondary" @click="emit('rs')">前往 RS 排行更新 <Icon name="arrow" :size="15"/></button></div>
   <template v-if="tab==='consensus'">
    <div class="focus-callout"><strong>{{report.consensus.as_of||'尚無日期'}} · {{report.consensus.observed}} / {{report.consensus.total}} 個追蹤分點有當日資料</strong><p v-if="rankMetric==='lots'">以各分點的「淨買賣超」判斷方向。先按同方向家數排名，再按同方向淨張數排序，各取前 30 檔；同一股票可同時出現在兩側。</p><p v-else>保留至少 {{minCount}} 家同方向分點的條件，再依同方向買賣超估算金額排序。金額＝同方向淨張數 × 1,000 股 × 當日收盤價；缺少收盤價者不列入金額排行。</p><p v-if="report.consensus.missing.length" class="focus-warning">缺少當日榜單：{{report.consensus.missing.join('、')}}；未將缺資料視為零。榜單未發現的個股交易仍可能遺漏。</p></div>
    <div class="focus-rankings"><section v-for="group in rankings" :key="group.side" class="panel"><header class="focus-section-heading"><h2 :class="group.side==='buy'?'positive':'negative'">{{group.title}}</h2><span>{{group.rows.length}} 檔 · 至少 {{minCount}} 家 · {{rankMetric==='lots'?'張數':'金額'}}排行</span></header><div class="table-scroll"><table class="focus-table"><thead><tr><th>股票／分點</th><th>同向／反向</th><th>{{rankMetric==='lots'?'同向淨張數':'同向金額'}} <small v-if="rankMetric==='value'">億元</small></th><th>合計淨額 <small>{{rankMetric==='lots'?'張':'億元'}}</small></th></tr></thead><tbody v-for="(row,i) in group.rows" :key="row.symbol"><tr><td><button class="focus-stock" :aria-expanded="expanded===group.side+row.symbol" @click="expanded=expanded===group.side+row.symbol?'':group.side+row.symbol"><span class="focus-rank">{{i+1}}</span><span><strong>{{row.name}}</strong><small>{{row.symbol}}<span v-if="report.tags[row.symbol]" class="focus-group-text" :title="report.tags[row.symbol]">{{report.tags[row.symbol]}}</span></small></span></button></td><td><strong :class="group.side==='buy'?'positive':'negative'">{{group.side==='buy'?row.buy_count:row.sell_count}} 家</strong><small>反向 {{group.side==='buy'?row.sell_count:row.buy_count}} 家</small></td><td>{{rankMetric==='lots'?fmt(group.side==='buy'?row.buy_lots:row.sell_lots):fmt((group.side==='buy'?row.buy_value:row.sell_value)!/1e8,2)}}</td><td :class="tone(row.net)">{{rankMetric==='lots'?signed(row.net):money(row.net_value)}}</td></tr><tr v-if="expanded===group.side+row.symbol"><td colspan="4" class="focus-contributors"><b>{{group.title}}分點</b><div v-for="b in group.side==='buy'?row.buyers:row.sellers" :key="b.broker+b.branch"><span>{{b.name}}</span><strong :class="tone(b.net)">{{rankMetric==='lots'?signed(b.net)+' 張':money(b.net_value)+' 億元'}}</strong></div></td></tr></tbody><tbody v-if="!group.rows.length"><tr><td colspan="4" class="empty-row">此日沒有符合條件的同步個股。</td></tr></tbody></table></div></section></div>
    <p class="major-footnote">點個股查看同方向分點明細。家數是已追蹤「分點」數，不是全市場券商家數；合計淨額包含反向分點，與同向張數或金額不同。金額由當日收盤價估算，不含交易成本。此頁只用已下載資料。</p>
   </template>
   <template v-else-if="tab==='turnover'">
    <div v-if="report.job" class="sync-status" :class="{'has-error':['partial','failed','interrupted'].includes(report.job.status)}" role="status"><Icon :name="running?'refresh':'info'" :size="16"/>{{report.job.message}}</div>
    <div class="focus-callout"><strong>每日成交金額前 30 名 · 從 2026/9/1 起保存 {{report.turnover.available_dates.length}} 個交易日</strong><p>合併上市、上櫃四碼普通股的實際成交金額，不含 ETF／ETN／權證。已保存日期直接沿用；開啟每日自動更新且本機程式運行時，會在設定的盤後時間補齊新日期。</p></div>
    <div v-if="sectorStats.length" class="focus-sectors"><button :class="{selected:!sector}" @click="sector=''">全部族群<br><small>{{fmt(totalAmount/1e8,2)}} 億 · 不重複</small></button><button v-for="g in sectorStats" :key="g.name" :class="{selected:sector===g.name}" @click="sector=sector===g.name?'':g.name">{{g.name}} <span>{{g.count}} 檔</span><br><small>{{fmt(g.amount/1e8,2)}} 億</small></button></div>
    <section class="panel"><header class="focus-section-heading"><h2>{{report.turnover.as_of||'尚未保存'}} 成交重心</h2><span>與族群流向共用分類 · {{report.sector_classification.snapshot||'未提供版本'}}</span></header><div class="table-scroll"><table class="focus-table focus-turnover"><thead><tr><th>名次</th><th>股票</th><th>成交金額 <small>億</small></th><th>收盤</th><th>累計入榜日數</th><th>所屬族群</th></tr></thead><tbody><tr v-for="row in turnoverRows" :key="row.symbol"><td>{{row.rank}}</td><td><strong>{{row.name}}</strong><small>{{row.symbol}} · {{row.market==='TWSE'?'上市':'上櫃'}}</small></td><td>{{fmt(row.amount/1e8,2)}}</td><td>{{fmt(row.close,2)}}</td><td>{{row.appearances}} 日</td><td><div class="focus-group-chips"><button v-for="name in memberships(row.symbol)" :key="name" @click="emit('sector',name)">{{name}} ↗</button><span v-if="!memberships(row.symbol).length" class="muted">未分類</span></div></td></tr><tr v-if="!turnoverRows.length"><td colspan="6" class="empty-row">{{report.turnover.as_of?'沒有符合搜尋或族群條件的個股。':'按「更新並補齊成交重心」，保存 9/1 起的歷史排名。'}}</td></tr></tbody></table></div></section>
    <p class="major-footnote">入榜日數只累計 9/1 至選定日期，未包含未保存日。分類直接使用族群流向字典，一檔可屬多個族群；各族群金額會完整計入該股，不能跨族群相加。全部金額只計每檔一次。未收錄者顯示未分類，使用目前字典而非歷史分類。點族群可查看上下游與成員。Yahoo 參考連結目前無法取得資料，本頁使用交易所盤後統計。</p><div class="major-sources"><a href="https://tw.stock.yahoo.com/rank/turnover" target="_blank" rel="noopener">Yahoo 成交值排行（參考）</a><a v-for="(url,i) in report.turnover.sources" :key="url" :href="url" target="_blank" rel="noopener">{{i===0?'證交所':'櫃買中心'}}當日資料</a><span v-if="report.turnover.fetched_at">保存 {{report.turnover.fetched_at.slice(0,16).replace('T',' ')}}</span></div>
   </template>
   <template v-else>
    <div class="focus-callout"><strong>{{report.rs.as_of||'尚未計算 RS'}} · RS20 > 60 且 RS YTD > 60，共 {{report.rs.rows.length}} 檔</strong><p>兩種期間使用同一份、同一天的個股 RS 計算結果。預設按兩者較低的 RS 排名；此交集包含 YTD 勝過或低於大盤的股票，另列與大盤差距。</p></div>
    <section class="panel"><div class="table-scroll"><table class="focus-table"><thead><tr><th>股票</th><th>20 日 RS%</th><th>YTD RS%</th><th>20 日漲幅</th><th>YTD 漲幅</th><th>YTD 較大盤 <small>百分點</small></th></tr></thead><tbody><tr v-for="row in rsRows" :key="row.symbol"><td><strong>{{row.name}}</strong><small>{{row.symbol}}<span v-if="report.tags[row.symbol]" class="focus-group-text" :title="report.tags[row.symbol]">{{report.tags[row.symbol]}}</span></small></td><td><b class="focus-rs">{{fmt(row.rs20,2)}}%</b></td><td><b class="focus-rs">{{fmt(row.rs_ytd,2)}}%</b></td><td :class="tone(row.return20)">{{signed(row.return20,2)}}%</td><td :class="tone(row.ytd_pct)">{{signed(row.ytd_pct,2)}}%</td><td :class="tone(row.excess_pct)">{{signed(row.excess_pct,2)}}</td></tr><tr v-if="!rsRows.length"><td colspan="6" class="empty-row">{{report.rs.as_of?'目前沒有符合條件的交集個股。':'請先前往 RS 排行計算資料。'}}</td></tr></tbody></table></div></section><p class="major-footnote">RS 是相對強度百分位，不是漲幅或 RSI；沿用 RS 排行的普通股範圍、價格基準及公司事件排除規則。更新 RS 後按「讀取最新本機統計」即可套用。</p>
   </template>
  </template>
 </div>
</template>
<style scoped>
.focus-group-chips{display:flex;flex-wrap:wrap;gap:6px;min-width:180px;max-width:290px;margin-left:auto;white-space:normal}.focus-group-chips button{padding:4px 7px;background:#edf3e7;color:#627d49;border:1px solid #dce5d4;border-radius:5px;font-size:.7rem}.focus-group-text{display:block;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:4px}

.focus-tabs{display:flex;gap:25px;border-bottom:1px solid #dce3d6;margin-bottom:22px}.focus-tabs button{padding:14px 2px;font-size:.9rem;color:#8a977e;border-bottom:3px solid transparent}.focus-tabs button.selected{font-weight:600;color:#506839;border-bottom-color:#7f9956}.focus-toolbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-bottom:18px;font-size:.79rem;color:#829273}.focus-toolbar label{display:flex;align-items:center;gap:8px}.focus-toolbar select,.focus-toolbar input{border:1px solid #dce3d7;padding:9px 10px;border-radius:6px;background:white;color:#566a48}.focus-toolbar .focus-number{width:65px}.focus-search{background:white;border:1px solid #dce3d7;border-radius:6px;padding-left:11px}.focus-toolbar .focus-search input{border:0;max-width:210px}.focus-toolbar .primary{margin-left:auto}.focus-callout{background:#eef3e9;border:1px solid #e0e7d9;border-radius:9px;padding:17px 20px;margin:0 0 22px;color:#708064;font-size:.79rem;line-height:1.8}.focus-callout strong{color:#526c45;font-weight:600;font-size:.88rem}.focus-callout p{margin:6px 0 0}.focus-callout .focus-warning{color:#a17c44}.focus-rankings{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.focus-rankings .panel{min-width:0;align-self:start}.focus-section-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:20px 23px}.focus-section-heading h2{font-size:1rem;margin:0}.focus-section-heading>span{font-size:.73rem;color:#929e86}.focus-table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}.focus-table th{text-align:right;padding:14px 16px;background:#f7f9f3;font-size:.74rem;color:#929f82;font-weight:400;border-bottom:1px solid #e6ebdf}.focus-table td{padding:16px;border-bottom:1px solid #ecf0e5;text-align:right;font-variant-numeric:tabular-nums}.focus-table th:first-child,.focus-table td:first-child{text-align:left}.focus-table small{display:block;font-size:.68rem;color:#97a38b;margin-top:5px}.focus-table th small{display:inline}.focus-table strong{font-weight:550}.focus-stock{display:flex;gap:9px;align-items:center;text-align:left}.focus-rank{color:#9cab8c;font-size:.72rem;min-width:17px}.focus-contributors{background:#f7faf3;white-space:normal}.focus-contributors>b{display:block;font-size:.75rem;color:#85956f;text-align:left;margin-bottom:12px}.focus-contributors>div{display:flex;justify-content:space-between;font-size:.76rem;gap:10px;padding:7px 0}.focus-sectors{display:flex;gap:10px;overflow-x:auto;padding:0 0 16px;margin-bottom:7px}.focus-sectors button{background:white;border:1px solid #dce5d4;border-radius:8px;text-align:left;flex-shrink:0;padding:13px 17px;color:#637b4a;line-height:1.8;font-size:.85rem}.focus-sectors button.selected{background:#edf4e2;border-color:#8ea870}.focus-sectors button small,.focus-sectors button span{font-size:.7rem;color:#889973}.focus-turnover td:nth-child(2),.focus-turnover th:nth-child(2){text-align:left}.focus-tag-editor{display:flex;gap:7px;justify-content:flex-end}.focus-tag-editor input{border:1px solid #dce4d5;border-radius:5px;padding:8px;width:170px;max-width:100%;color:#5d7451;background:#fcfdf9;font-size:.76rem}.focus-tag-editor button{border:1px solid #dce4d5;border-radius:5px;font-size:.72rem;padding:6px 9px}.focus-tag-editor button:disabled{opacity:.4}.focus-rs{background:#eef4e7;color:#617d3f;border-radius:5px;padding:5px 8px;font-weight:550}
@media(max-width:1200px){.focus-rankings{grid-template-columns:1fr}.focus-table td,.focus-table th{padding:14px}.focus-toolbar .primary{margin-left:0}}
@media(max-width:650px){.focus-tabs{gap:16px;overflow:auto}.focus-tabs button{font-size:.76rem;white-space:nowrap}.focus-section-heading{padding:18px}.focus-table{font-size:.77rem}.focus-table td,.focus-table th{padding:13px 11px}.focus-toolbar{gap:10px}}
</style>
